tasks.solution:
class Shape:
    def area(self):
        raise NotImplementedError

class Square(Shape):
    def __init__(self, a):
        self.a = a
    def area(self):
        return self.a ** 2

class Circle(Shape):
    def __init__(self, r):
        self.r = r
    def area(self):
        return 3.14159 * self.r ** 2

kinds = {"square": Square, "circle": Circle}
for _ in range(int(input())):
    kind, size = input().split()
    print(round(kinds[kind](float(size)).area(), 2))

